#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    priority_queue<long long> pq;  // max-heap by default
    for (int i = 0; i < n; i++) { long long w; cin >> w; pq.push(w); }
    while (pq.size() > 1) {
        long long y = pq.top(); pq.pop();
        long long x = pq.top(); pq.pop();
        if (y != x) pq.push(y - x);
    }
    cout << (pq.empty() ? 0 : pq.top()) << "\n";
    return 0;
}

