#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    cin >> n >> k;
    // max-heap of the k best so far: the worst of them is on top, ready to be replaced
    priority_queue<tuple<long long, int, int>> heap;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        heap.push({1LL * x * x + 1LL * y * y, x, y});
        if ((int)heap.size() > k) heap.pop();
    }
    vector<tuple<long long, int, int>> best;
    while (!heap.empty()) { best.push_back(heap.top()); heap.pop(); }
    reverse(best.begin(), best.end());
    for (auto& [d, x, y] : best) cout << x << " " << y << "\n";
    return 0;
}

