#include <bits/stdc++.h>
using namespace std;
int main() {
    int k;
    cin >> k;
    vector<vector<long long>> lists(k);
    for (auto& l : lists) { int m; cin >> m; l.resize(m); for (auto& x : l) cin >> x; }
    using Item = tuple<long long, int, int>;  // value, list, position
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    for (int i = 0; i < k; i++) if (!lists[i].empty()) heap.push({lists[i][0], i, 0});
    vector<long long> out;
    while (!heap.empty()) {
        auto [v, i, j] = heap.top(); heap.pop();
        out.push_back(v);
        if (j + 1 < (int)lists[i].size()) heap.push({lists[i][j + 1], i, j + 1});
    }
    if (out.empty()) cout << "-\n";
    for (size_t i = 0; i < out.size(); i++) cout << out[i] << (i + 1 < out.size() ? " " : "\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    priority_queue<long long, vector<long long>, greater<long long>> heap;
    for (int i = 0; i < n; i++) { long long x; cin >> x; heap.push(x); }
    long long cost = 0;  // can exceed 2^31
    while (heap.size() > 1) {
        long long a = heap.top(); heap.pop();
        long long b = heap.top(); heap.pop();
        cost += a + b;
        heap.push(a + b);
    }
    cout << cost << "\n";
    return 0;
}

