import heapq

input()
low, high = [], []       # low: max-heap (negated) of the smaller half; high: min-heap of the larger half
out = []
for x in map(int, input().split()):
    if not low or x <= -low[0]:
        heapq.heappush(low, -x)
    else:
        heapq.heappush(high, x)
    # rebalance: low has the same size as high, or one more
    if len(low) > len(high) + 1:
        heapq.heappush(high, -heapq.heappop(low))
    elif len(high) > len(low):
        heapq.heappush(low, -heapq.heappop(high))
    out.append(str(-low[0]))  # the largest of the lower half is the lower median
print(" ".join(out))

