#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    priority_queue<long long> low;                                   // lower half (max-heap)
    priority_queue<long long, vector<long long>, greater<long long>> high;  // upper half (min-heap)
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
        cout << low.top() << (i + 1 < n ? " " : "\n");
    }
    return 0;
}

